#!/usr/bin/env bash
# Claudia's own Cloudflare Tunnel (docs/DECISIONS.md B21), separate from Bull and Bear's tunnel,
# whose config is generated by that project and whose daemon runs as root.
#
# Idempotent: creates the `claudia` tunnel if missing (credentials in ~/.claudia/secrets),
# writes ~/.claudia/tunnel/config.yml, validates it, and installs the com.aroop.claudia.tunnel
# LaunchAgent. It never touches ~/.cloudflared/config.yml and never changes DNS: it prints the
# two DNS commands for the owner to run (see ops/go-live.md).
set -euo pipefail

CLAUDIA_HOME="${CLAUDIA_HOME:-$HOME/.claudia}"
REPO_DIR="$(cd "$(dirname "$0")/.." && pwd)"
CLOUDFLARED="${CLOUDFLARED:-$(command -v cloudflared)}"
TUNNEL_NAME="claudia"
CREDS="$CLAUDIA_HOME/secrets/tunnel-$TUNNEL_NAME.json"
CONFIG="$CLAUDIA_HOME/tunnel/config.yml"
PLIST="$HOME/Library/LaunchAgents/com.aroop.claudia.tunnel.plist"
log() { echo "[tunnel] $*"; }

mkdir -p "$CLAUDIA_HOME/tunnel" "$CLAUDIA_HOME/logs" "$CLAUDIA_HOME/secrets"
chmod 700 "$CLAUDIA_HOME/secrets"

if [ ! -f "$CREDS" ]; then
  log "creating tunnel $TUNNEL_NAME"
  "$CLOUDFLARED" tunnel create --credentials-file "$CREDS" "$TUNNEL_NAME" >/dev/null
  chmod 600 "$CREDS"
fi
TUNNEL_ID="$(node -e 'console.log(JSON.parse(require("fs").readFileSync(process.argv[1],"utf8")).TunnelID)' "$CREDS")"
log "tunnel id: $TUNNEL_ID"

cat > "$CONFIG" <<CFG
# Claudia's own Cloudflare Tunnel (docs/DECISIONS.md B21). Separate from Bull and Bear's tunnel.
tunnel: $TUNNEL_ID
credentials-file: $CREDS

ingress:
  - hostname: claudia.aroopbiswal.com
    service: http://127.0.0.1:8787
  - hostname: ntfy.aroopbiswal.com
    service: http://127.0.0.1:8790
  - service: http_status:404
CFG
chmod 600 "$CONFIG"
"$CLOUDFLARED" tunnel --config "$CONFIG" ingress validate >/dev/null
log "config valid: $CONFIG"

sed -e "s#{{CLOUDFLARED}}#$CLOUDFLARED#" -e "s#{{HOME_DIR}}#$CLAUDIA_HOME#g" \
  "$REPO_DIR/ops/launchd/com.aroop.claudia.tunnel.plist.template" > "$PLIST.tmp"
mv "$PLIST.tmp" "$PLIST"
uid="$(id -u)"
launchctl bootout "gui/$uid/com.aroop.claudia.tunnel" >/dev/null 2>&1 || true
for _ in $(seq 1 40); do launchctl print "gui/$uid/com.aroop.claudia.tunnel" >/dev/null 2>&1 || break; sleep 0.5; done
launchctl bootstrap "gui/$uid" "$PLIST"
log "LaunchAgent com.aroop.claudia.tunnel running"

cat <<MSG
[tunnel] DNS is a human step. Pass --config so cloudflared uses this tunnel, not the one named in
[tunnel] ~/.cloudflared/config.yml (it silently prefers that one otherwise):
  cloudflared tunnel --config $CONFIG route dns --overwrite-dns $TUNNEL_ID claudia.aroopbiswal.com
  cloudflared tunnel --config $CONFIG route dns --overwrite-dns $TUNNEL_ID ntfy.aroopbiswal.com
MSG
